function brandOf(url){ var u; try{ u=new URL(String(url||""),location.href); }catch(e){ return null; } if(!/^https?:$/.test(u.protocol)) return null;
  var h=u.hostname.toLowerCase().replace(/^www\./,""), p=u.pathname||"";
  if(/(^|\.)atlassian\.net$/.test(h)) return brandEntry(/^\/wiki(\/|$)/.test(p)?"confluence":"jira");
  if(h==="docs.google.com"&&/^\/forms\//.test(p)) return brandEntry("googleforms");
  for(var i=0;i<BRAND_HOSTS.length;i++){ var x=BRAND_HOSTS[i][0]; if(h===x||h.slice(-x.length-1)==="."+x) return brandEntry(BRAND_HOSTS[i][1]); }
  return null; }
function brandEntry(k){ var i=BRAND_ICONS[k], m=BRAND_MONO[k]; return i?{key:k,name:i.n,color:"#"+i.c,d:i.d}:m?{key:k,name:m.n,color:"#"+m.c,mono:m.t}:null; }
